/* ==UserStyle==
@name boringproxy Catppuccin
@namespace github.com/catppuccin/userstyles/styles/boringproxy
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/boringproxy
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/boringproxy/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aboringproxy
@description Soothing pastel theme for boringproxy
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("boring.example.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body {
      background: @base;
    }
    main {
      background: @crust;
    }
    .content {
      border-color: @overlay0;
    }

    //Side Menu
    .menu {
      background: @mantle;
    }
    .menu-item {
      background: @crust;
    }
    .menu-item:hover {
      background: @surface2;
      color: @accent;
    }
    .menu-item:any-link {
      color: @text;
    }

    // Right SIde Button
    .button {
      border-color: @accent;
      background-color: @crust;
      color: @subtext1;
    }
    .button:hover {
      color: @surface0;
      background-color: @accent;
      border-color: @crust;
    }

    // Top Headers
    .list {
      background-color: @crust;
    }

    .list-item {
      color: @accent;
    }
    // Tunnel Table
    .tn-tunnel-link {
      color: @subtext1;
      text-decoration: none;
    }

    .tn-tunnel-table__cell {
      color: @text;
    }
    body a {
      color: @text;
    }
    body a:visited {
      color: @accent;
    }

    .tn-attribute__name {
      color: @text;
    }
    .tn-attribute__value {
      color: @subtext0;
    }
    //Tunnel Adding
    .tunnel-adder h1 {
      color: @text;
    }

    .input {
      color: @text;
    }
    .input input {
      background-color: @crust;
      color: @subtext0;
      border-color: @accent;
    }

    .input select {
      background-color: @crust;
      color: @subtext0;
      border-color: @accent;
    }

    // Token Adding
    .token-adder {
      color: @text;
    }
    .token-adder select {
      background-color: @crust;
      color: @subtext0;
      border-color: @accent;
    }

    // Client Adding
    .client-adder {
      color: @text;
    }
    .client-adder select {
      background-color: @crust;
      color: @subtext0;
      border-color: @accent;
    }
    .client-adder input {
      background-color: @crust;
      color: @subtext0;
      border-color: @accent;
    }

    // User Adding
    .user-adder {
      color: @text;
    }
    .user-adder input {
      background-color: @crust;
      color: @subtext0;
      border-color: @accent;
    }
    // dialog
    .dialog__content {
      background-color: @crust;
      color: @text;
    }
  }
}

